 function snapshotSource(d,page,label='PDF source'){const url=d?.local_pdf_url;const suffix=Number.isInteger(page)&&page>0?'#page='+page:'';const local=typeof url==='string'&&/^http:\/\/127\.0\.0\.1:8767\/pdf\/[a-f0-9]{64}\.pdf$/.test(url)?`<a href="${esc(url+suffix)}" target="_blank" rel="noopener">${esc(label)}</a>`:'';return `${local}${local?' · ':''}${safeLink(d?.official_url,'Official documents')}<small>${esc(d?.filename||'Document reference unavailable')}${page?' · PDF page '+num(page):''}</small>`;}
 async function loadSnapshot(r){const c=currentFor(r);if(!c)return;if(snapshotCache.get(r.source_native_id)?.run===currentSnapshot().run)return;snapshotCache.delete(r.source_native_id);if(snapshotPending.has(r.source_native_id))return snapshotPending.get(r.source_native_id);const pending=(async()=>{try{if(!/^snapshot-details\/[a-f0-9]{64}\.json$/.test(c.detail_file))throw Error('Unexpected snapshot detail route.');const response=await root.fetch(new URL(c.detail_file,scriptUrl||root.document.baseURI));if(!response.ok)throw Error('Current records HTTP '+response.status);const x=await response.json();if(x.schema!=='SRPE_CURRENT_SOURCE_DETAIL_V1'||x.run!==currentSnapshot().run||x.source_native_id!==r.source_native_id)throw Error('Current record identity mismatch.');snapshotCache.set(r.source_native_id,x);if(snapshotCache.size>6)snapshotCache.delete(snapshotCache.keys().next().value);if(state.selected===r.source_native_id&&state.tab==='snapshot')render();}catch(e){const target=root.document?.querySelector('[data-nd-snapshot-status]');if(target)target.textContent=e.message;}finally{snapshotPending.delete(r.source_native_id);}})();snapshotPending.set(r.source_native_id,pending);return pending;}
 function legacyCurrentOverview(r){const c=currentFor(r);if(!c)return '';const a=c.asking,t=c.recorded.recent||{},sz=c.sizes,max=Math.max(a.median_rate_hkd_psf||0,t.median_rate_hkd_psf||0,1),bar=(label,value,count,colour)=>`<div class="ug-nd-rate-bar"><span>${esc(label)}</span><strong>${rate(value)}</strong><div><i style="width:${value?Math.max(2,value/max*100):0}%;background:${colour}"></i></div><small>${num(count)} ${label==='Asking'?'priced unit/basis records':'eligible recorded entries'}</small></div>`;return `<section data-nd-current-overview>${c.source_notice?'<details><summary>Vendor notice</summary><p>'+esc(c.source_notice)+'</p></details>':''}<p class="ug-nd-date">Snapshot captured ${esc(String(currentSnapshot().captured||'').slice(0,10))} · ${c.coverage.holds?num(c.coverage.holds)+' coverage holds':'No known processing holds; coverage review required'}</p><div class="ug-nd-rate-pair">${bar('Asking',a.median_rate_hkd_psf,a.rows,'#ab673d')}${bar('Recorded · last 365 days',t.median_rate_hkd_psf,t.rate_sample_count,'#337fa1')}</div><p class="ug-nd-note">Asking uses latest listed revisions, document dates ${esc(a.document_dates?.[0]||'—')} to ${esc(a.document_dates?.at(-1)||'—')}. Recorded uses dated ASP entries, ${esc(t.period_start||'—')} to ${esc(t.period_end||'—')}. Different units and payment terms can affect the comparison; no discount or price-change percentage is inferred.</p><div class="ug-nd-metrics"><div><span>Median asking price</span><strong>${money(a.median_price_hkd)}</strong></div><div><span>Median recorded price · 365 days</span><strong>${money(t.median_price_hkd)}</strong></div><div><span>Observed apartment sizes</span><strong>${num(sz.min_sqft)}–${num(sz.max_sqft)} sq ft</strong></div><div><span>Area-supported apartments</span><strong>${num(sz.units)}</strong></div></div><p class="ug-nd-note">${esc(a.ranking_eligible?'Generic published asking prices; no incentive adjustment.':'Asking summary held where price-list coverage or comparable payment basis is unresolved; parsed quotes remain inspectable.')} Rates use price divided by published saleable sq ft. Listed prices do not establish availability. Apartment ranges cover supported parsed units.</p><div class="ug-nd-actions">${button('current-records','Inspect current records & source PDFs',r.source_native_id)}${button('pin','Compare developments',r.source_native_id)}</div></section>`;}
 function legacySnapshotView(r){const c=currentFor(r),cached=snapshotCache.get(r.source_native_id),x=cached?.run===currentSnapshot()?.run?cached:null;if(!c)return '<p>No current snapshot is available for this source.</p>';if(!x)return '<p data-nd-snapshot-status role="status">Loading current price, area and register records…</p>';const mode=state.snapshotKind||'ASKING';let rows=mode==='ASKING'?x.asking:mode==='AREA'?x.areas:x.recorded;const sort=state.snapshotSort||(mode==='AREA'?'size':mode==='ASKING'?'rate':'date');rows=[...rows].sort((a,b)=>sort==='size'?(b.saleable_sqft||0)-(a.saleable_sqft||0):sort==='rate'?(b.rate_hkd_psf||0)-(a.rate_hkd_psf||0):sort==='price'?(b.price_hkd||0)-(a.price_hkd||0):String(b.date||b.document_date||'').localeCompare(String(a.date||a.document_date||'')));const page=state.page,visible=rows.slice(page*50,page*50+50);return `<section data-nd-current-records><div class="ug-nd-actions">${snapshotTabs(r,mode)}</div><div class="ug-nd-actions">Sort ${[['rate','Highest rate'],['price','Highest price'],['size','Largest area'],['date','Newest date']].map(([key,label])=>button('snapshot-sort',label,r.source_native_id,`data-nd-sort="${key}" aria-pressed="${sort===key}"`)).join('')}</div><p>${num(rows.length)} ${mode==='ASKING'?'published unit/basis quotes':mode==='AREA'?'supported apartment areas':'recorded entries'}. ${mode==='ASKING'?'Payment basis stays with each quote; no incentive adjustment.':''}</p><div class="ug-nd-table"><table><thead><tr><th>Block / floor / unit</th><th>${mode==='RECORDED'?'Agreement date / state':'Document date / basis'}</th><th>Price · HK$</th><th>Saleable sq ft</th><th>HK$/sq ft</th><th>Source</th></tr></thead><tbody>${visible.map(v=>`<tr><td>${esc(v.property_label||[v.block,v.floor,v.unit].filter(Boolean).join(' / '))}</td><td>${esc(mode==='RECORDED'?v.date:v.document_date||x.documents[v.document_id]?.date)}<small>${esc(mode==='RECORDED'?v.lifecycle||'':v.price_basis||'Brochure area')}${mode==='RECORDED'&&!v.in_sample?' · excluded from median':''}</small>${v.payment_terms_raw?.length?'<details><summary>Payment wording</summary><p>'+esc(v.payment_terms_raw.join(' '))+'</p></details>':''}</td><td>${money(v.price_hkd)}</td><td>${num(v.saleable_sqft)}</td><td>${rate(v.rate_hkd_psf)}</td><td>${snapshotSource(x.documents[v.document_id],v.physical_page)}${v.area_source?'<details><summary>Area evidence</summary>'+snapshotSource(x.documents[v.area_source.document_id],v.area_source.physical_page)+'</details>':''}</td></tr>`).join('')}</tbody></table></div><p>${rows.length?num(page*50+1)+'–'+num(page*50+visible.length)+' of '+num(rows.length):'No qualified rows; this does not establish zero prices or sales.'}</p><div class="ug-nd-actions">${page?button('previous','Previous',r.source_native_id):''}${(page+1)*50<rows.length?button('next','More records',r.source_native_id):''}</div><details><summary>Documents and coverage (${num(x.holds.length)} holds)</summary><ul>${Object.values(x.documents).map(d=>'<li>'+snapshotSource(d,null)+' · '+esc(d.content_state||d.state||'retained area evidence')+'</li>').join('')}</ul><ul>${x.holds.slice(0,80).map(h=>'<li>'+esc(h.reason||h.error||'Review required')+'</li>').join('')}</ul></details></section>`;}

 const registry=()=>{const x=root.UGA_NEW_DEVELOPMENTS_AREA_CANDIDATES?.current_area_registry;return x?.schema==='SRPE_CURRENT_AREA_SITE_REGISTRY_V1'&&x.run===currentSnapshot()?.run?x:null;};
 const registryFor=r=>registry()?.records?.[r?.source_native_id]||null;
 const registryCache=new Map(),registryPending=new Map();
 async function loadRegistry(r){
  const all=registry(),summary=registryFor(r);if(!all||!summary)return;
  if(registryCache.get(r.source_native_id)?.fingerprint===all.fingerprint)return;
  if(registryPending.has(r.source_native_id))return registryPending.get(r.source_native_id);
  const pending=(async()=>{try{
   if(!/^registry-details\/[a-f0-9]{64}\.json$/.test(summary.detail_file))throw Error('Unexpected current-area detail route.');
   const response=await root.fetch(new URL(summary.detail_file,scriptUrl||root.document.baseURI));
   if(!response.ok)throw Error('Current-area records HTTP '+response.status);
   const value=await response.json();
   if(value.schema!=='SRPE_CURRENT_AREA_SOURCE_DETAIL_V1'||value.run!==all.run||value.source_native_id!==r.source_native_id||value.recorded.length!==summary.priced_entries||value.areas.length!==summary.sizes.units)throw Error('Current-area record identity/count mismatch.');
   registryCache.set(r.source_native_id,{...value,fingerprint:all.fingerprint});
   if(registryCache.size>6)registryCache.delete(registryCache.keys().next().value);
   if(state.selected===r.source_native_id&&state.tab==='snapshot')render();
  }catch(e){const target=root.document?.querySelector('[data-nd-registry-status]');if(target)target.textContent=e.message;}finally{registryPending.delete(r.source_native_id);}})();
  registryPending.set(r.source_native_id,pending);return pending;
 }
 function snapshotTabs(r,mode){return (registryFor(r)?['ASKING','RECORDED','AREA','ACTIVITY']:['ASKING','RECORDED','AREA']).map(k=>button('snapshot-kind',({ASKING:'Asking prices',RECORDED:'Recorded entries',AREA:'Unit sizes',ACTIVITY:'Monthly activity'})[k],r.source_native_id,`data-nd-kind="${k}" aria-pressed="${mode===k}"`)).join('');}
 function currentOverviewBase(r){
  const c=currentFor(r),g=registryFor(r);if(!c||!g)return legacyCurrentOverview(r);
  const a=c.asking,t=g.recent,p=c.recorded.recent||{},sz=g.sizes,max=Math.max(a.median_rate_hkd_psf||0,t.median_rate_hkd_psf||0,1);
  const bar=(label,v,n,colour)=>`<div class="ug-nd-rate-bar"><span>${esc(label)}</span><strong>${rate(v)}</strong><div aria-hidden="true"><i style="width:${v?Math.max(2,v/max*100):0}%;background:${colour}"></i></div><small>${num(n)} rate samples</small></div>`;
  const latest=a.document_dates?.at(-1)||'unavailable';
  return `<section class="ug-nd-current-summary" data-nd-current-overview><p class="ug-market-meta">Snapshot ${esc(registry().as_at)} · recorded window: latest 365 days</p><div class="ug-nd-rate-pair">${bar('Asking · HK$/sq ft',a.median_rate_hkd_psf,a.rows,'#9b7960')}${bar('Recorded · current area · HK$/sq ft',t.median_rate_hkd_psf,t.rate_sample_count,'#46798a')}</div><p>${num(t.rate_sample_count)} of ${num(t.priced_entries)} eligible priced register entries have a current-area rate in this window.</p><div class="v2-sheet-metric-grid">${[['Median asking price',money(a.median_price_hkd)],['Median recorded price · 365 days',money(p.median_price_hkd)],['Supported size range',num(sz.min_sqft)+'–'+num(sz.max_sqft)+' sq ft'],['Units with area evidence',num(sz.units)]].map(([label,value])=>'<div class="v2-sheet-metric"><span>'+esc(label)+'</span><strong>'+esc(value)+'</strong></div>').join('')}</div><div class="ug-nd-actions">${button('current-records','Records & source PDFs',r.source_native_id)}${root.UGA_MARKET_REPORT_VIEW?.mapButtons('nd','this development',r.source_native_id)||''}${button('pin','Compare developments',r.source_native_id)}</div><details><summary>Dates, coverage and rate definitions</summary><p>Asking documents through ${esc(latest)} · register ${esc(c.recorded.snapshot_date||'unavailable')}. Listed prices do not establish availability.</p><p>Recorded rates divide register prices by the same unit’s current published saleable area. They do not establish the area applicable at the original agreement date. The separate dated-evidence sample has ${num(p.rate_sample_count)} entries, median ${rate(p.median_rate_hkd_psf)}.</p><p>Asking and recorded samples have different units, dates and payment terms. No discount or price-change percentage is inferred. Register entries are not completed-sale counts; incentives are not deducted.</p><p>Size ranges describe supported current evidence, not proven development-wide extremes. ${g.document_holds?num(g.document_holds)+' brochure document(s) have a page-coordinate hold.':''} ${esc(a.ranking_eligible?'Generic published asking basis.':'Asking headline held where list coverage or payment basis is unresolved; parsed prices remain inspectable.')}</p>${c.source_notice?'<p>Vendor notice: '+esc(c.source_notice)+'</p>':''}</details></section>`;
 }
 function currentOverview(r){return currentOverviewBase(r)+(root.UGA_MARKET_REPORT_VIEW?.developmentPeers(r)||'');}
 function registryView(r,x,g,mode){
  const tabs=`<div class="ug-nd-actions">${snapshotTabs(r,mode)}</div>`;
  if(mode==='ACTIVITY'){
   const rows=[...g.monthly].sort((a,b)=>b.register_event_month.localeCompare(a.register_event_month));
   return `<section>${tabs}<p>Monthly eligible ASP register entries, using retained event dates. Counts and prices cover the price sample; rate columns retain their own sample sizes. These are not completed-sale counts.</p><div class="ug-nd-table"><table><thead><tr><th>Month</th><th>Priced entries</th><th>Median price · HK$</th><th>Current-area rate sample</th><th>Median HK$/sq ft · current area</th><th>Dated-rate sample</th></tr></thead><tbody>${rows.map(v=>`<tr><td>${esc(v.register_event_month)}</td><td>${num(v.priced_register_entries)}</td><td>${money(v.median_price_hkd)}</td><td>${num(v.current_area_rate_samples)}</td><td>${rate(v.median_current_area_rate_hkd_psf)}</td><td>${num(v.qualified_rate_samples)}</td></tr>`).join('')}</tbody></table></div></section>`;
  }
  const docs={...x.documents,...g.documents},joined=new Map(g.recorded.map(v=>[v.id,v]));
  let rows=mode==='AREA'?g.areas:x.recorded.map(v=>({...v,currentArea:joined.get(v.id)}));
  const sort=state.snapshotSort||(mode==='AREA'?'size':'date');
  rows=[...rows].sort((a,b)=>sort==='size'?(b.currentArea?.saleable_sqft??b.saleable_sqft??0)-(a.currentArea?.saleable_sqft??a.saleable_sqft??0):sort==='rate'?(b.currentArea?.rate_hkd_psf??0)-(a.currentArea?.rate_hkd_psf??0):sort==='price'?(b.price_hkd||0)-(a.price_hkd||0):String(b.date||b.document_date||'').localeCompare(String(a.date||a.document_date||'')));
  const visible=rows.slice(state.page*50,state.page*50+50);
  const controls=`<div class="ug-nd-actions">Sort ${[['rate','Highest current-area rate'],['price','Highest price'],['size','Largest area'],['date','Newest date']].map(([key,label])=>button('snapshot-sort',label,r.source_native_id,`data-nd-sort="${key}" aria-pressed="${sort===key}"`)).join('')}</div>`;
  const body=visible.map(v=>{
   if(mode==='AREA')return `<tr><td>${esc([v.block,v.floor,v.unit].filter(Boolean).join(' / '))}</td><td>${esc(v.document_date)}</td><td>—</td><td>${num(v.saleable_sqft)}</td><td>—</td><td>—</td><td>${snapshotSource(docs[v.document_id],v.physical_page)}</td></tr>`;
   const a=v.currentArea;return `<tr><td>${esc(v.property_label||[v.block,v.floor,v.unit].filter(Boolean).join(' / '))}</td><td>${esc(v.date)}<small>${esc(v.lifecycle||'')}${!v.in_sample?' · excluded from rate samples':''}</small>${a?.hold?'<small>'+esc(a.hold==='BLOCK_CONTEXT_REVIEW_REQUIRED'?'Block identity needs review':'Current-area match pending')+'</small>':''}${v.payment_terms_raw?.length?'<details><summary>Payment wording</summary><p>'+esc(v.payment_terms_raw.join(' '))+'</p></details>':''}</td><td>${money(v.price_hkd)}</td><td>${num(a?.saleable_sqft)}</td><td>${rate(a?.rate_hkd_psf)}</td><td>${rate(v.rate_hkd_psf)}</td><td>${snapshotSource(docs[v.document_id],v.physical_page)}${a?.area_source?'<details><summary>Current area source</summary>'+snapshotSource(docs[a.area_source.document_id],a.area_source.physical_page)+'</details>':''}${v.area_source?'<details><summary>Dated area source</summary>'+snapshotSource(docs[v.area_source.document_id],v.area_source.physical_page)+'</details>':''}</td></tr>`;
  }).join('');
  return `<section>${tabs}${controls}<p>${num(rows.length)} ${mode==='AREA'?'supported unit-area records':'register entries'}. Current-area and dated-evidence rates are separate columns. Unknown values remain blank; current-area rates require explicit block labels.</p><div class="ug-nd-table"><table><thead><tr><th>Block / floor / unit</th><th>${mode==='AREA'?'Area document date':'Agreement date / state'}</th><th>Price · HK$</th><th>Current published sq ft</th><th>HK$/sq ft · current area</th><th>HK$/sq ft · dated evidence</th><th>Sources</th></tr></thead><tbody>${body}</tbody></table></div><p>${rows.length?num(state.page*50+1)+'–'+num(state.page*50+visible.length)+' of '+num(rows.length):'No supported rows; this does not establish zero sales or stock.'}</p><div class="ug-nd-actions">${state.page?button('previous','Previous',r.source_native_id):''}${(state.page+1)*50<rows.length?button('next','More records',r.source_native_id):''}</div><details><summary>Documents and coverage</summary><ul>${Object.values(docs).map(d=>'<li>'+snapshotSource(d,null)+' · '+esc(d.content_state||d.state||'Area evidence')+'</li>').join('')}</ul><ul>${[...(x.holds||[]),...g.holds].slice(0,80).map(h=>'<li>'+esc(h.reason||h.error||'Review required')+'</li>').join('')}</ul></details></section>`;
 }
 function snapshotView(r){
  const summary=registryFor(r),mode=state.snapshotKind||'ASKING';if(!summary||mode==='ASKING')return legacySnapshotView(r);
  const x=snapshotCache.get(r.source_native_id),g=registryCache.get(r.source_native_id);
  if(x?.run!==currentSnapshot()?.run||g?.fingerprint!==registry()?.fingerprint)return `<div class="ug-nd-actions">${snapshotTabs(r,mode)}</div><p data-nd-registry-status role="status">Loading current area and register evidence…</p>`;
  return registryView(r,x,g,mode);
 }

 function retainedOverview(r){const p=r.pricing||{},trial=p.candidate_entry_rates||[],s=areaFor(r),c=candidateFor(r);return `<div class="ug-nd-metrics"><div><span>Retained entries</span><strong>${num(r.entry_count)}</strong></div><div><span>Median recorded price</span><strong>${money(p.median_recorded_price_hkd)}</strong></div><div><span>Median recorded HK$/sq ft</span><strong data-nd-area-median>${rate(s?.summary.median_rate_hkd_psf)}</strong></div><div><span>${s?'Area-matched entries':c?'Latest brochure area matches':'Candidate area matches'}</span><strong>${s?areaCoverage(r):c?num(c.matched_entries):num(trial.length)}</strong></div></div><p>${esc(r.coverage?.label||'Coverage pending')} · ${num(r.exclusion_count)} held records · ${num(p.price_sample_count)} entries in the displayed price sample.</p><p>Price-sample period: ${esc(p.period_start||'—')} to ${esc(p.period_end||'—')}.</p>${priceNote()}${s?areaSupport(r):c?'':trial.length?`<div class="ug-nd-area"><strong>${trial.length} candidate unit rates available</strong><p>THE PASEO price-list trial matches exact floor/unit references. The document copy and revision applicability remain under review.</p>${button('tab','Inspect unit pricing',r.source_native_id,'data-nd-tab="units"')}</div>`:'<p class="ug-nd-note">Unit-level saleable area matching is still required for comparable rates.</p>'}<div class="ug-nd-actions">${button('pin',state.pinned===r.source_native_id?'Choose comparison':'Compare with another development',r.source_native_id)}${button('tab','Browse retained entries',r.source_native_id,'data-nd-tab="units"')}</div>`;}
 function overview(r){return currentFor(r)?currentOverview(r)+(r.entry_count?'<details><summary>Retained historical register summary</summary>'+retainedOverview(r)+'</details>':''):retainedOverview(r);}
 function unitRows(xs){return xs.map(x=>`<tr><td>${esc(x.floor||'—')} / ${esc(x.unit||'—')}<small>${esc(x.native_grain||'')} · ${esc(x.block||'')}</small></td><td>${esc(x.date||'—')}</td><td>${money(x.price_hkd)}</td><td>${esc(x.lifecycle||x.date_type||'—')}<small>${esc((x.event_kinds||[]).join(' · '))}${x.termination_date?' · termination '+esc(x.termination_date):''}</small></td>${areaCells(x)}</tr>`).join('');}
 function unitsView(r){const all=unitCache.get(r.source_native_id);if(!all)return `<p data-nd-units-status>${r.unit_file?'Loading retained unit entries…':'No unit-level browser product is available for this source.'}</p>`;const rows=all.slice(state.page*50,state.page*50+50);return `<p>${all.length} retained entries · showing ${state.page*50+1}–${state.page*50+rows.length}. Dates and agreement states retain their source meaning.</p><div class="ug-nd-table"><table><thead><tr><th>Floor / unit</th><th>Source date</th><th>Recorded price</th><th>State</th><th>Saleable sq ft</th><th>HK$/sq ft</th></tr></thead><tbody data-nd-unit-rows>${unitRows(rows)}</tbody></table></div><p class="ug-nd-note">${areaFor(r)?'Each area source opens its document and page. Price-list and revision-history support are labelled separately; revised, terminated and non-proceeded entries are excluded from the median.': candidateFor(r)?'Areas shown use the latest retained brochure. Historical rates remain held until revision applicability is reviewed.': 'Area and rate cells marked Candidate use the document-copy trial. Other blanks mean an area match is pending.'}</p><div class="ug-nd-actions">${state.page?button('previous','Previous entries',r.source_native_id):''}${(state.page+1)*50<all.length?button('next','More entries',r.source_native_id):''}</div>`;}
 function evidence(r){const l=locationFor(r.source_native_id);return `${areaEvidence(r)}<h3>Source and coverage</h3><p>${esc(r.source_remark||'No additional vendor notice in the retained catalogue.')}</p><dl class="ug-nd-evidence"><dt>Register date</dt><dd>${esc(r.register_update||'Unavailable')}</dd><dt>Dated events</dt><dd>${num(r.event_count)}</dd><dt>Held records</dt><dd>${num(r.exclusion_count)}</dd><dt>Area source status</dt><dd>${esc(areaFor(r)?areaBasis(areaFor(r)):candidateFor(r)?'Latest brochure areas matched; historical rates held':r.brochure_status||'Pending')}</dd><dt>Map location</dt><dd>${esc(l?.status==='SOURCE_POINT'?'Source-provided Development/Phase point; approximate display location.':l?.status==='OUTSIDE_HK_REVIEW_REQUIRED'?'Source coordinate is outside Hong Kong and has been withheld from the layer.':'No usable source coordinate; retained in the catalogue.')}</dd></dl><p>${safeLink(r.source_reference,'Inspect official source documents')} ${safeLink(r.pricing?.candidate_document_url,'Inspect candidate area document')}</p><details><summary>Identity and provenance</summary><p>Source-native Development/Phase ${esc(r.source_native_id)}. This source context is separate from a canonical Development or unit identity. Points are not Building footprints or ownership boundaries.</p><p>Snapshot ${esc(r.snapshot_sha256||'not bound')}. Catalogue: ${esc(data()?.catalogue_vintage||'date unavailable')}.</p></details>`;}
 function development(r){return `<article class="v2-report-sheet ug-nd-report">${header(r)}${buildingLink(r)}${candidateNotice(r)}<nav class="ug-nd-tabs" aria-label="Development detail">${(currentFor(r)?['overview','snapshot','units','evidence']:['overview','units','evidence']).map(t=>button('tab',t==='overview'?'Overview':t==='snapshot'?'Current records':t==='units'?'Retained history':'Sources & coverage',r.source_native_id,`data-nd-tab="${t}" aria-pressed="${state.tab===t}"`)).join('')}</nav>${state.tab==='building'?buildingContextView(r):state.tab==='overview'?overview(r):state.tab==='snapshot'?snapshotView(r):state.tab==='units'?unitsView(r):evidence(r)}<p data-nd-status role="status"></p></article>`;}
