 function remember(){if(!root.UGA_V2_REPORT_HOST?.isExternal())state.history=[];else state.history.push({view:state.view,selected:state.selected,tab:state.tab,page:state.page,choices:state.choices,branch:state.branch,query:state.query,pinned:state.pinned});if(state.history.length>20)state.history.shift();}
